# Custom generator wrapper to handle corrupted images
class SafeGenerator:
    def __init__(self, generator):
        self.generator = generator
        self.iterator = None

    def __iter__(self):
        self.iterator = iter(self.generator)
        return self

    def __next__(self):
        while True:
            try:
                return next(self.iterator)
            except Exception as e:
                print(f"Skipping batch due to error: {e}")
                continue

    def __len__(self):
        return len(self.generator)

    def reset(self):
        self.generator.reset()
        self.iterator = None

# Create safe generators
